(()=>{'use strict';
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='chihome-preview'){c=e.data.config;welcomeShown=false;render()}});
const root=window.CHIHOME_ELEMENTOR?document.body:document.getElementById('chihome-app');let c,lang,filter='all',welcomeShown=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const safe=u=>/^(https?:\/\/|mailto:|tel:|assets\/|\/|#)/i.test(u||'')?esc(u):'';
const asset=u=>u?.startsWith('assets/')?(window.CHIHOME_ASSET_BASE||'')+u:u;
const t=(en,vi)=>c?.copy?.[en]?.[lang]??(lang==='vi'?vi:en);const local=o=>typeof o==='object'?o?.[lang]||o?.en||'':o;
function track(event,data={}){if(!c.analytics.enabled)return;window.dataLayer=window.dataLayer||[];window.dataLayer.push({event,...data});}
function logo(){return c.logo?`<img src="${safe(asset(c.logo))}" alt="${esc(c.brand)}">`:`<i>✧</i>${esc(c.brand)}<small>Saigon riverside living</small>`}
function link(label,href,cls='btn',extra=''){if(href==='#contact'&&!c.sections.some(s=>s.id==='contact'&&s.visible))href=c.contact.phoneUrl||'https://chihome.vn/';if(href==='#apartments'&&!c.sections.some(s=>s.id==='apartments'&&s.visible))href=c.contact.phoneUrl||'https://chihome.vn/';return `<a class="${cls}" href="${safe(href)||'#contact'}" ${extra}>${esc(label)}</a>`}
const paths=['M4 20h24M7 20V9l9-6 9 6v11M12 20v-8h8v8','M16 28s10-10 10-17a10 10 0 0 0-20 0c0 7 10 17 10 17ZM16 7a4 4 0 1 0 0 8 4 4 0 0 0 0-8','M3 27h26M6 27V12h7v15m0-6V5h8v22m0-12h6v12M16 9h2m-2 5h2','M4 24V12h24v12M4 19h24M7 12V8h18v4M4 24v4m24-4v4M9 15h5m4 0h5','M16 3l4 8 9 2-7 7 2 9-8-4-8 4 2-9-7-7 9-2Z'];
function render(){filter='all';document.documentElement.lang=lang;document.title=t('ChiHome | Saigon Riverside Living','ChiHome | Căn hộ lưu trú Thủ Thiêm');Object.entries(c.tokens).forEach(([k,v])=>{if(/^#[0-9a-f]{6}$/i.test(v))document.documentElement.style.setProperty('--'+k,v)});const h=c.hero[lang];
root.innerHTML=`<header><div class="wrap"><a href="#" class="logo" aria-label="ChiHome">${logo()}</a><nav aria-label="${t('Main navigation','Điều hướng chính')}">${[['apartments','Apartments','Căn hộ'],['reviews','Reviews','Đánh giá'],['contact','Contact','Liên hệ'],['about','About ChiHome','ChiHome']].filter(x=>c.sections.some(s=>s.id===x[0]&&s.visible)).map(([id,en,vi])=>`<a href="#${id}">${t(en,vi)}</a>`).join('')}</nav><div class="language" aria-label="Language"><button data-lang="vi" class="${lang==='vi'?'active':''}" aria-pressed="${lang==='vi'}">VI</button><span>/</span><button data-lang="en" class="${lang==='en'?'active':''}" aria-pressed="${lang==='en'}">EN</button></div>${link('BOOKING','#contact')}<button class="menu-toggle" aria-label="${t('Open navigation','Mở menu')}" aria-expanded="false">☰</button></div></header>
<main><section class="hero" aria-label="${esc(h.eyebrow)}"><img src="${safe(asset(c.hero.image))}" alt="${t('ChiHome living room overlooking the Saigon River','Phòng khách ChiHome nhìn ra sông Sài Gòn')}" fetchpriority="high" width="2000" height="1333"><div class="wrap"><div class="eyebrow">${esc(h.eyebrow)}</div><h1>${esc(h.title).replace(/\n(.+)/,'\n<em>$1</em>')}</h1><p>${esc(h.subtitle)}</p><div class="hero-actions">${link(h.cta,'#apartments','btn gold-bg')}${c.hero.video?`<button class="text-link hero-tour" data-hero-video>${t('Watch room tour','Xem room tour')} ↗</button>`:''}</div></div><div class="hero-note">THỦ THIÊM · HO CHI MINH CITY</div></section>
${c.sections.filter(s=>s.visible).map(s=>sections[s.id]?.()||'').join('')}</main>
<footer><div class="wrap"><div class="footer-top"><div><a href="#" class="logo">${logo()}</a><p>${t('Thoughtful spaces.\nMemorable stays.\nYour Saigon story starts here.','Không gian tinh tế.\nKỳ nghỉ đáng nhớ.\nCâu chuyện Sài Gòn bắt đầu từ đây.')}</p></div><div class="footer-contact"><a href="mailto:${esc(c.contact.email)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 5h20v14H2zM2 5l10 8L22 5"/></svg>${esc(c.contact.email)}</a><a href="${safe(c.contact.phoneUrl)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3h4l2 5-3 2c2 4 3 5 6 6l2-3 5 2v4c0 3-5 3-10-1S2 8 3 5z"/></svg>${esc(c.contact.phone)}</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ChiHome · Saigon Riverside Living</span><span>Thu Thiem · Ho Chi Minh City</span></div></div></footer><div class="mobile-cta"><a href="#" class="logo mobile-brand" aria-label="ChiHome">${logo()}</a>${link(t('Booking','Booking'),'#contact','btn')}</div><dialog id="detail-dialog"><button class="dialog-close" aria-label="${t('Close','Đóng')}">×</button><div class="dialog-body"></div></dialog>`;bind();showWelcomePopup();}
function options(){return c.apartments.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}
function cards(){return c.apartments.filter(a=>filter==='all'||a.id===filter).map(a=>`<article class="card" data-apartment="${esc(a.id)}"><button type="button" class="card-image" data-detail="${esc(a.id)}" aria-label="${esc(t('View details','Xem chi tiết'))}: ${esc(a.name)}"><img src="${safe(asset(a.image))}" alt="${esc(a.name)}" loading="lazy" width="1024" height="683"></button><div class="card-info"><div class="location">${esc(a.location)}</div><h3><button type="button" class="card-title" data-detail="${esc(a.id)}">${esc(a.name)}</button></h3><p>${esc(a[lang])}</p><div class="features">${(a.amenities[lang]||[]).map(x=>`<span>· ${esc(x)}</span>`).join('')}</div><div class="collection-card-action"><a class="btn card-inquiry" href="#contact" data-book="${esc(a.id)}">${t('Booking inquiry','Tư vấn đặt phòng')}</a></div></div></article>`).join('')}
function findUnit(id){return c.apartments.flatMap(collection=>collection.units||[]).find(unit=>unit.id===id)}
function unitCards(collection){return (collection.units||[]).map(unit=>`<article class="unit-card" data-unit="${esc(unit.id)}"><button type="button" class="unit-photo" data-unit-detail="${esc(unit.id)}" aria-label="${esc(t('View apartment photos','Xem ảnh căn hộ'))}: ${esc(unit.name)}"><img src="${safe(asset(unit.image))}" alt="${esc(unit.name)}" loading="lazy" width="1200" height="800"><span class="unit-code">${esc(unit.code)}</span></button><div class="unit-content"><div class="unit-collection-name">${esc(collection.name)}</div><h4><button type="button" data-unit-detail="${esc(unit.id)}">${esc(unit.name)}</button></h4><div class="unit-specs">${unit.area?`<span>${esc(unit.area)} m²</span>`:''}${unit.bedrooms?`<span>${esc(unit.bedrooms)} ${t('bedrooms','phòng ngủ')}</span>`:''}${unit.bathrooms?`<span>${esc(unit.bathrooms)} ${t('bathrooms','phòng tắm')}</span>`:''}</div>${local(unit.features)?.length?`<div class="unit-features">${local(unit.features).map(feature=>`<span>${esc(feature)}</span>`).join('')}</div>`:''}<div class="unit-card-actions"><button type="button" data-unit-detail="${esc(unit.id)}">${t('View photos','Xem ảnh')}</button><button type="button" class="btn" data-unit-inquiry="${esc(unit.id)}">${t('Get advice now','Tư vấn ngay')}</button></div></div></article>`).join('')}
function renderUnitCatalog(){
 const catalog=root.querySelector('#unit-catalog');
 catalog.hidden=filter==='all';if(catalog.hidden){catalog.innerHTML='';return;}
 const collections=c.apartments.filter(collection=>filter==='all'||collection.id===filter);
 const count=collections.reduce((sum,collection)=>sum+(collection.units||[]).length,0);
 const title=filter==='all'?t('All apartments','Tất cả căn hộ'):collections[0]?.name||'';
 catalog.innerHTML=`<section class="unit-catalog-section" aria-labelledby="unit-catalog-title"><div class="unit-catalog-heading"><div><div class="eyebrow gold">${t('EXPLORE THE APARTMENTS','KHÁM PHÁ TỪNG CĂN HỘ')}</div><h3 id="unit-catalog-title">${esc(title)}</h3><p>${count} ${t('apartments to discover','căn hộ để khám phá')}</p></div></div><div class="unit-grid">${collections.map(unitCards).join('')}</div><p class="unit-catalog-note">${t('Apartment details are taken from the supplied albums. Rates and availability are confirmed by ChiHome.','Thông tin căn hộ theo album được cung cấp. Giá và tình trạng phòng sẽ được ChiHome xác nhận.')}</p></section>`;
}
function inquireUnit(unit){
 const form=root.querySelector('#inquiry');if(!form)return;const dialog=root.querySelector('#detail-dialog');if(dialog.open)dialog.close();
 form.elements.apartment.value=unit.parentCollection;
 const notes=form.elements.notes;let existing=notes.value;const old=notes.dataset.unitContext;if(old&&existing.startsWith(old))existing=existing.slice(old.length).trimStart();
 const context=t('Apartment of interest: ','Căn hộ quan tâm: ')+unit.name+' ['+unit.code+']';notes.dataset.unitContext=context;notes.value=(context+'\n'+existing).slice(0,2000);
 document.getElementById('contact').scrollIntoView();form.elements.name.focus({preventScroll:true});track('unit_inquiry_click',{unit:unit.id,collection:unit.parentCollection});
}

const sections={
why:()=>`<section id="why" class="intro wrap"><div class="eyebrow gold">CHIHOME</div><h2>${t('A little more space.\nA lot more to experience.','Nâng tầm không gian sống')}</h2><p>${t('A place to settle in, reconnect, and see Saigon from a fresh perspective. Explore ChiHome’s apartment collections around Thủ Thiêm.','Lựa chọn để nghỉ ngơi, kết nối và ngắm nhìn Sài Gòn từ góc nhìn mới.\nChiHome tại Thủ Thiêm.')}</p><div class="benefits">${[['Premium interiors','Nội thất tinh tế','Spaces with personality','Không gian sang trọng'],['Connected location','Vị trí trung tâm','Discover Thủ Thiêm','Giữa lòng thành phố'],['A fresh perspective','Góc nhìn mới mẻ','Views vary by apartment','Những góc đẹp của Sài Gòn'],['Room to feel at home','Thoải mái như nhà','Your own living space','Không gian sống riêng tư'],['A stay that fits','Lưu trú phù hợp','Ask for a tailored quote','Theo nhu cầu của khách hàng']].map((x,i)=>`<div class="benefit"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="${paths[i]}"/></svg><h3>${t(x[0],x[1])}</h3><p>${t(x[2],x[3])}</p></div>`).join('')}</div></section>`,
apartments:()=>`<section id="apartments" class="section apartments wrap"><div class="section-head"><div><div class="eyebrow gold">FEEL AT HOME</div><h2>${t('Apartment listings','Danh sách căn hộ')}</h2></div></div><div class="apartment-grid">${cards()}</div><div id="unit-catalog" hidden></div></section>`,
location:()=>`<section id="location" class="section wrap"><div class="location-grid"><div class="location-photo"><img src="${safe(asset(c.hero.image))}" alt="${t('Saigon River and skyline from a ChiHome apartment','Sông Sài Gòn và thành phố từ căn hộ ChiHome')}" loading="lazy" width="2000" height="1333"></div><div class="location-copy"><div class="eyebrow gold">${t('THE CITY, AT YOUR OWN PACE','THÀNH PHỐ, THEO NHỊP RIÊNG')}</div><h2>${t('Close to the city.\nCloser to the river.','Gần nhịp phố, bên dòng sông.')}</h2><p>${t('Let Thủ Thiêm be your starting point. Cross Ba Son Bridge, discover the city’s food scene, or enjoy an unhurried evening by the river.','Bắt đầu hành trình từ Thủ Thiêm. Qua cầu Ba Son, khám phá ẩm thực thành phố hoặc dành một buổi chiều thong thả bên sông.')}</p>${link(t('Explore the area on Google Maps','Khám phá khu vực trên Google Maps'),'https://www.google.com/maps/search/?api=1&query=Thu+Thiem+Ho+Chi+Minh+City','text-link','target="_blank" rel="noopener"')}<div class="places">${c.articles.map(a=>`<a href="${safe(a.url)}" target="_blank" rel="noopener"><div>${esc(local(a.title))}<small>${esc(local(a.subtitle))}</small></div></a>`).join('')}</div></div></div></section>`,
reviews:()=>{const approved=c.reviews.filter(r=>r.permission===true&&r.source);return `<section id="reviews" class="reviews wrap" aria-labelledby="guest-stories-title"><h2 id="guest-stories-title">${t('Every stay has a story.','Đánh giá của khách hàng')}</h2>${approved.length?`<div class="guest-stories-grid">${approved.map(r=>`<article class="guest-story"><div class="guest-story-profile">${r.avatar?`<img src="${safe(asset(r.avatar))}" alt="" width="48" height="48" loading="lazy">`:''}<div><h3>${esc(r.author)}</h3>${r.date?`<time datetime="${esc(r.date)}">${esc(r.date.split('-').reverse().join('/'))}</time>`:''}</div><span class="guest-story-quote" aria-hidden="true">“</span></div>${r.rating?`<div class="guest-story-rating" aria-label="${esc(r.rating)} / 5">${'★'.repeat(Math.max(0,Math.min(5,Math.floor(Number(r.rating)))))}</div>`:''}<blockquote><p>${esc(local(r.text))}</p></blockquote></article>`).join('')}</div><p class="review-privacy-note">${t('Guest names are pseudonyms; profile images are AI-generated privacy replacements.','Tên khách là tên thay thế; ảnh đại diện do AI tạo để bảo vệ riêng tư.')}</p>`:`<p class="review-placeholder">${t('Verified guest stories are being prepared. We’ll share them here once publication permission is confirmed.','Đánh giá từ khách thực tế đang được chuẩn bị và sẽ xuất hiện khi đã xác minh cùng quyền sử dụng.')}</p>`}</section>`},
contact:()=>`<section id="contact" class="section booking"><div class="wrap booking-grid"><div class="booking-copy"><div class="eyebrow gold">${t('LET’S PLAN YOUR STAY','LÊN KẾ HOẠCH LƯU TRÚ')}</div><h2>${t('Your next chapter\nin Saigon starts here.','Bắt đầu câu chuyện\nSài Gòn của bạn.')}</h2><p>${t('Tell us a little about your trip. We’ll help you explore the options and confirm availability for your dates.','Chia sẻ một chút về chuyến đi. ChiHome sẽ tư vấn lựa chọn và xác nhận tình trạng phòng theo ngày bạn mong muốn.')}</p></div><form id="inquiry"><label><span>${t('Full name','Họ và tên')} *</span><input name="name" autocomplete="name" required maxlength="120"></label><label><span>${t('Email or phone','Email hoặc số điện thoại')} *</span><input name="contact" autocomplete="email" required maxlength="160"></label><label class="full apartment-field"><span>${t('Your preferred apartment','Căn hộ bạn quan tâm')}</span><select name="apartment" aria-describedby="apartment-hint"><option value="">${t('Let ChiHome guide me','Để ChiHome tư vấn')}</option>${options()}</select><small id="apartment-hint">${t('Choose an apartment, or let us suggest a suitable stay.','Chọn căn hộ, hoặc để ChiHome gợi ý.')}</small></label><label><span>${t('Check-in','Ngày nhận phòng')} *</span><input type="date" name="checkin" required></label><label><span>${t('Check-out','Ngày trả phòng')} *</span><input type="date" name="checkout" required></label><label><span>${t('Number of guests','Số khách')} *</span><input type="number" name="guests" min="1" max="50" value="2" required></label><label><span>${t('Preferred language','Ngôn ngữ')}</span><select name="language"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="vi" ${lang==='vi'?'selected':''}>Tiếng Việt</option></select></label><label class="full"><span>${t('Notes','Ghi chú')}</span><textarea name="notes" rows="2" maxlength="2000" placeholder="${t('Notes','Ghi chú')}."></textarea></label><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="consent full"><input type="checkbox" name="consent" required><span>${t('I agree to the use of my details to respond to this inquiry.','Tôi đồng ý sử dụng thông tin để phản hồi yêu cầu này.')}</span></label><button class="btn gold-bg full inquiry-submit" type="submit">${t('Booking','Booking')}</button><div class="full form-status" role="status" aria-live="polite"></div></form><div class="contact-line booking-hotline"><div class="eyebrow">${t('Contact us now','Liên Hệ Ngay')}</div><a href="${safe(c.contact.phoneUrl)}">${esc(c.contact.phone)}</a><p>${t('An inquiry does not reserve an apartment. Booking is confirmed separately after availability and terms are agreed.','Yêu cầu tư vấn chưa giữ chỗ căn hộ. Đặt phòng được xác nhận riêng sau khi thống nhất tình trạng phòng và điều khoản.')}</p></div></div></section>`,
about:()=>`<section id="about" class="section wrap about-chihome" aria-labelledby="about-title"><div class="about-heading"><div class="eyebrow gold">${esc(local(c.about.eyebrow))}</div><h2 id="about-title">${esc(local(c.about.title))}</h2><p>${esc(local(c.about.intro))}</p></div><div class="about-layout"><div class="about-story">${(c.about.paragraphs[lang]||c.about.paragraphs.en).map(p=>`<p>${esc(p)}</p>`).join('')}${link(t('View the collection','Xem bộ sưu tập'),'#apartments','text-link')}</div><aside class="about-facts" aria-label="${esc(local(c.about.title))}">${c.about.details.map(d=>`<div class="about-fact"><h3>${esc(local(d.title))}</h3><p>${esc(local(d.text))}</p></div>`).join('')}<a class="about-phone" href="${safe(c.contact.phoneUrl)}">${esc(c.contact.phone)}</a></aside></div></section>`};

// One welcome banner per page load. All cover content follows the configured Hero.
function showWelcomePopup(){
 const settings=c.welcomePopup;if(!settings?.enabled||welcomeShown)return;
 welcomeShown=true;
 const hero=c.hero[lang],copy=settings[lang]||settings.en||{};
 const content=settings.useHeroContent!==false?hero:copy;
 const popup=document.createElement('dialog');
 popup.className='welcome-popup';popup.id='welcome-popup';
 popup.setAttribute('aria-labelledby','welcome-title');popup.setAttribute('aria-describedby','welcome-subtitle');
 popup.innerHTML=`<button type="button" class="welcome-close" aria-label="${t('Close','Đóng')}" autofocus>×</button><div class="welcome-cover"><img src="${safe(asset(settings.image||c.hero.image))}" alt="${t('ChiHome apartment overlooking Saigon','Căn hộ ChiHome nhìn ra Sài Gòn')}" width="2000" height="1333"><div class="welcome-copy"><div class="eyebrow">${esc(content.eyebrow||hero.eyebrow)}</div><h2 id="welcome-title">${esc(content.title||hero.title).replace(/\n(.+)/,'<br><em>$1</em>')}</h2><p id="welcome-subtitle">${esc(content.subtitle||hero.subtitle)}</p></div></div><div class="welcome-actions">${link(copy.bookingLabel||t('Book now','Đặt phòng ngay'),'#contact','btn gold-bg','data-welcome-book')}${link(copy.hotlineLabel||'Hotline',c.contact.phoneUrl,'btn outline','data-welcome-hotline')}</div>`;
 root.append(popup);
 const dismiss=()=>popup.close();popup.querySelector('.welcome-close').onclick=dismiss;
 popup.addEventListener('click',e=>{if(e.target!==popup)return;const r=popup.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dismiss()});
 popup.querySelector('[data-welcome-book]').addEventListener('click',()=>{dismiss();const form=root.querySelector('#inquiry');if(form)requestAnimationFrame(()=>form.elements.name.focus({preventScroll:true}))});
 popup.querySelector('[data-welcome-hotline]').addEventListener('click',dismiss);
 popup.addEventListener('close',()=>popup.remove(),{once:true});
 popup.showModal();
}

function openApartment(p){
 track('apartment_view',{apartment:p.id});
 const pics=p.gallery?.length?p.gallery:[p.image];let index=0;
 const article=local(p.article)||{title:p.name,intro:p[lang],paragraphs:[]};
 const d=modal(`<div class="apartment-detail-heading"><div class="eyebrow gold">THỦ THIÊM · SAIGON RIVERSIDE LIVING</div><h2 id="apartment-detail-title">${esc(p.name)}</h2><p>⌖ ${esc(p.location)}</p></div><figure class="detail-gallery" tabindex="0" role="region" aria-roledescription="${t('carousel','thư viện ảnh')}" aria-label="${esc(p.name)} — ${t('photo gallery','thư viện ảnh')}"><img id="gallery-img" src="${safe(asset(pics[0]))}" alt="${esc(p.name)}" width="1400" height="933" draggable="false"><button type="button" class="gallery-arrow gallery-prev" id="prev-img" ${pics.length<2?'hidden':''} aria-label="${t('Previous photo','Ảnh trước')}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button><button type="button" class="gallery-arrow gallery-next" id="next-img" ${pics.length<2?'hidden':''} aria-label="${t('Next photo','Ảnh tiếp')}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg></button><div class="gallery-caption"><span id="gallery-caption-text"></span><span id="gallery-count" aria-live="polite" aria-atomic="true">1 / ${pics.length}</span></div></figure><p class="detail-image-note">${t('Photos from ChiHome’s collection; the exact unit and view are confirmed during your inquiry.','Ảnh thuộc danh mục ChiHome; căn cụ thể và hướng nhìn được xác nhận khi tư vấn.')}</p><article class="apartment-article"><div class="eyebrow gold">${t('ABOUT THE RESIDENCES','GIỚI THIỆU KHU CĂN HỘ')}</div><h3>${esc(article.title)}</h3><p class="article-intro">${esc(article.intro)}</p>${(article.paragraphs||[]).map(block=>`<h4>${esc(block.heading)}</h4><p>${esc(block.text)}</p>`).join('')}<p class="detail-source">${t('Overview based on publicly available ChiHome information.','Tổng hợp từ thông tin công khai của ChiHome.')} · 04/11/2026</p></article>${p.parentCollection?`<div class="unit-detail-actions"><button type="button" class="btn gold-bg" data-unit-inquiry="${esc(p.id)}">${t('Inquire about this apartment','Tư vấn căn hộ này')} ↗</button></div>`:''}`);
 if(p.parentCollection){d.querySelector('.detail-source').textContent=t('Details from the supplied apartment album.','Thông tin từ album căn hộ được cung cấp.');d.querySelector('.detail-image-note').textContent=t('Photos from the album for apartment ','Ảnh từ album căn ')+p.code+'.';}
 d.classList.add('apartment-detail');d.setAttribute('aria-labelledby','apartment-detail-title');
 const gallery=d.querySelector('.detail-gallery');const captions=p.galleryCaptions?.[lang]||[];
 const update=()=>{const img=d.querySelector('#gallery-img');img.src=asset(pics[index]);img.alt=`${p.name} — ${captions[index]||t('Photo','Ảnh')} ${index+1}`;d.querySelector('#gallery-count').textContent=`${index+1} / ${pics.length}`;d.querySelector('#gallery-caption-text').textContent=captions[index]||p.name;};
 const move=step=>{index=(index+step+pics.length)%pics.length;update()};update();
 d.querySelector('#prev-img').onclick=()=>move(-1);d.querySelector('#next-img').onclick=()=>move(1);
 gallery.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowLeft'?-1:1)}});
 let gesture=null;gallery.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.target.closest('button'))return;gesture={x:e.clientX,y:e.clientY,id:e.pointerId};gallery.setPointerCapture(e.pointerId)});
 gallery.addEventListener('pointerup',e=>{if(!gesture||e.pointerId!==gesture.id)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;gesture=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.3)move(dx<0?1:-1)});
 gallery.addEventListener('pointercancel',()=>gesture=null);
}

function modal(html){const d=root.querySelector('#detail-dialog');d.classList.remove('apartment-detail','thank-you-dialog','form-alert-dialog');d.removeAttribute('aria-describedby');d.removeAttribute('aria-labelledby');d.querySelector('.dialog-body').innerHTML=html;d.showModal();return d}
function dates(form){form.noValidate=true;form.addEventListener('input',e=>clearFieldError(e.target));const a=form.elements.checkin,b=form.elements.checkout;[a,b].forEach(input=>{if(input.parentElement.classList.contains('date-control'))return;const wrap=document.createElement('span');wrap.className='date-control';const display=document.createElement('span');display.className='date-display';display.setAttribute('aria-hidden','true');const icon=document.createElement('span');icon.className='date-icon';icon.setAttribute('aria-hidden','true');input.before(wrap);wrap.append(display,icon,input);const sync=()=>{const parts=input.value.split('-');display.textContent=parts.length===3?`${parts[2]}/${parts[1]}/${parts[0]}`:'dd/mm/yyyy';display.classList.toggle('is-empty',!input.value)};input.addEventListener('input',sync);input.addEventListener('change',sync);input.addEventListener('click',()=>{if(typeof input.showPicker==='function'){try{input.showPicker()}catch{}}});form.addEventListener('reset',()=>setTimeout(sync,0));sync()});function localToday(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}function nextDay(value){const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}function validate(){const today=localToday();a.min=today;const start=a.value&&a.value>=today?a.value:today;b.min=nextDay(start);a.setCustomValidity(a.value&&a.value<today?t('Choose today or a future date.','Chọn hôm nay hoặc ngày tương lai.'):'');b.setCustomValidity(b.value&&b.value<b.min?t('Check-out must be after check-in and today.','Ngày trả phòng phải sau ngày nhận phòng và hôm nay.'):'')}function rejectInvalid(input){validate();if(!input.value||input.validity.valid)return;const message=input.validationMessage;input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));clearFieldError(input);const error=document.createElement('span');error.className='field-error';error.id='inquiry-'+input.name+'-error';error.setAttribute('role','alert');error.textContent=message;input.closest('label').append(error);input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',error.id);validate()}[a,b].forEach(input=>{input.addEventListener('focus',validate);input.addEventListener('input',validate);input.addEventListener('change',()=>rejectInvalid(input))});validate();form._validateDates=validate;}
function bind(){root.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;localStorage.setItem('chihome-language',lang);render()});root.querySelector('.menu-toggle').onclick=e=>{const n=root.querySelector('nav');n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',n.classList.contains('open'))};root.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{root.querySelector('nav').classList.remove('open');root.querySelector('.menu-toggle').setAttribute('aria-expanded','false')});root.querySelector('.dialog-close').onclick=()=>root.querySelector('dialog').close();root.querySelector('dialog').addEventListener('close',()=>root.querySelector('.dialog-body').innerHTML='');root.querySelector('dialog').onclick=e=>{if(e.target===e.currentTarget&& (e.offsetX<0||e.offsetY<0||e.offsetX>e.target.clientWidth||e.offsetY>e.target.clientHeight))e.currentTarget.close()};
root.querySelectorAll('#inquiry').forEach(dates);const f=root.querySelector('#inquiry');if(f){f.elements.contact.addEventListener('input',()=>f.elements.contact.setCustomValidity(''));f.onsubmit=submit;}
}
root.addEventListener('click',e=>{const a=e.target.closest('a,button');if(!a)return;if(a.matches('a[href^="#"],.btn'))track('cta_click',{label:a.textContent.trim(),target:a.getAttribute('href')||''});if(a.dataset.book){const f=root.querySelector('#inquiry');if(f)f.elements.apartment.value=a.dataset.book;}
if(a.dataset.unitDetail){const unit=findUnit(a.dataset.unitDetail);if(unit)openApartment(unit);}
if(a.dataset.unitInquiry){const unit=findUnit(a.dataset.unitInquiry);if(unit)inquireUnit(unit);}
if(a.dataset.detail){const p=c.apartments.find(x=>x.id===a.dataset.detail);if(p)openApartment(p);}
if(a.hasAttribute('data-hero-video')){modal(`<h2>${t('Room tour','Khám phá căn hộ')}</h2><video controls playsinline preload="metadata" src="${safe(c.hero.video)}"></video>`)}
if(a.dataset.video!==undefined){const v=c.videos[Number(a.dataset.video)];const url=new URL(v.url);let embed='';if(['youtube.com','www.youtube.com','youtu.be'].includes(url.hostname)){const id=url.hostname==='youtu.be'?url.pathname.slice(1):url.searchParams.get('v')||url.pathname.split('/').pop();if(/^[\w-]{11}$/.test(id))embed=`<iframe src="https://www.youtube-nocookie.com/embed/${id}" title="${esc(local(v.title))}" allowfullscreen></iframe>`;}else if(/\.(mp4|webm)(\?.*)?$/i.test(url.pathname))embed=`<video controls playsinline preload="metadata" src="${safe(v.url)}"></video>`;modal(`<h2>${esc(local(v.title))}</h2>${embed||link(t('Watch the room tour','Xem room tour'),v.url,'btn','target="_blank" rel="noopener"')}`);track('room_tour_open',{title:local(v.title)})}
if(a.dataset.legal){e.preventDefault();modal(`<h2>${a.dataset.legal==='privacy'?t('Your data, thoughtfully handled','Bảo vệ thông tin của bạn'):t('Booking terms','Điều khoản đặt phòng')}</h2><p>${a.dataset.legal==='privacy'?t('Preview: this form does not send or store personal details until a backend is connected. Once connected, your name, contact details, dates, preferences and campaign source will be sent to ChiHome for this inquiry only. Do not include payment or passport details. The official retention period, data controller and privacy contact must be configured before publication.','Bản thử nghiệm: biểu mẫu chưa gửi hay lưu thông tin cá nhân khi chưa kết nối backend. Khi kết nối, họ tên, liên hệ, ngày ở, nhu cầu và nguồn chiến dịch sẽ được gửi cho ChiHome để xử lý yêu cầu. Không nhập thông tin thanh toán hoặc hộ chiếu. Cần bổ sung đơn vị quản lý dữ liệu, thời hạn lưu và liên hệ bảo mật trước khi xuất bản.'):t('Terms are pending verification. Availability, total price, payment schedule and cancellation conditions must be confirmed by ChiHome before booking. No payment is collected on this preview.','Điều khoản đang chờ xác minh. ChiHome cần xác nhận phòng, tổng giá, thời hạn thanh toán và chính sách hủy trước khi đặt. Bản thử nghiệm không thu tiền.')}</p>`)} });
function utm(){const p=new URLSearchParams(location.search),keys=['utm_source','utm_medium','utm_campaign','utm_term','utm_content'];let data={};try{data=JSON.parse(sessionStorage.getItem('chihome-attribution')||'{}')}catch{}if(keys.some(k=>p.has(k))){data={};keys.forEach(k=>{if(p.has(k))data[k]=p.get(k).slice(0,250)});sessionStorage.setItem('chihome-attribution',JSON.stringify(data))}return data;}
function showThankYou(data,id){
 const d=modal(`<article class="thank-you-letter"><div class="thank-you-brand"><div class="logo">${logo()}</div></div><div class="thank-you-mark" aria-hidden="true"><svg viewBox="0 0 100 100" fill="none"><circle class="success-ring-track" cx="50" cy="50" r="43"/><circle class="success-ring" cx="50" cy="50" r="43" pathLength="1"/><path class="success-tick" d="m30 51 13 13 27-29" pathLength="1"/></svg></div><h2 id="thank-you-title">${esc(t('Thank you!','Cảm ơn bạn!'))}</h2><div class="thank-you-message"><p>${esc(t('Dear','Thân gửi'))} <strong>${esc(data.name)}</strong>,</p><p id="thank-you-description">${esc(t('Thank you for trusting and choosing ChiHome. We have received your inquiry and will contact you using the details you provided as soon as possible.','Cảm ơn bạn đã tin tưởng và lựa chọn ChiHome. Chúng tôi đã nhận được yêu cầu của bạn và sẽ liên hệ theo thông tin bạn cung cấp trong thời gian sớm nhất.'))}</p></div><div class="thank-you-footer">${id?`<span>${esc(t('Reference','Mã yêu cầu'))}: <strong>CH-${esc(String(id).padStart(4,'0'))}</strong></span>`:''}<a href="${safe(c.contact.phoneUrl)}">Hotline: ${esc(c.contact.phone)}</a></div></article>`);
 d.classList.add('thank-you-dialog');d.setAttribute('aria-labelledby','thank-you-title');d.setAttribute('aria-describedby','thank-you-description');
 d.addEventListener('close',()=>d.removeAttribute('aria-describedby'),{once:true});
}
function clearFieldError(field){
 if(!field?.name)return;const id='inquiry-'+field.name+'-error';document.getElementById(id)?.remove();field.removeAttribute('aria-invalid');
 const described=(field.getAttribute('aria-describedby')||'').split(' ').filter(x=>x&&x!==id);if(described.length)field.setAttribute('aria-describedby',described.join(' '));else field.removeAttribute('aria-describedby');
}
function showFieldError(field){
 const missing=field.validity.valueMissing||!field.value.trim();
 const message=missing?t('Please fill in your information','Vui lòng điền thông tin'):field.validationMessage;
 const error=document.createElement('span');error.className='field-error';error.id='inquiry-'+field.name+'-error';error.setAttribute('role','alert');error.textContent=message;
 field.closest('label').append(error);field.setAttribute('aria-invalid','true');field.setAttribute('aria-describedby',[(field.getAttribute('aria-describedby')||''),error.id].filter(Boolean).join(' '));
}
async function submit(e){e.preventDefault();const f=e.currentTarget;f._validateDates();const contact=f.elements.contact.value.trim();const valid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact)||/^\+?[\d\s().-]{8,25}$/.test(contact);f.elements.name.setCustomValidity(f.elements.name.value.trim()?'':t('Please fill in your information','Vui lòng điền thông tin'));f.elements.name.oninput=()=>f.elements.name.setCustomValidity('');f.elements.contact.setCustomValidity(!contact||valid?'':t('Enter a valid email or phone number.','Nhập email hoặc số điện thoại hợp lệ.'));Array.from(f.elements).forEach(clearFieldError);if(!f.checkValidity()){const invalid=Array.from(f.elements).filter(el=>el.willValidate&&!el.validity.valid);invalid.forEach(showFieldError);invalid[0].scrollIntoView({block:'center',behavior:'smooth'});invalid[0].focus({preventScroll:true});return;}const data=Object.fromEntries(new FormData(f));if(data.website)return;data.utm=utm();data.consent=true;const status=f.querySelector('.form-status');if(!c.backend.endpoint){status.textContent=t('Not sent: this preview has no connected backend. Please call ChiHome to check these dates.','Chưa gửi: bản thử nghiệm chưa kết nối backend. Vui lòng gọi ChiHome để kiểm tra ngày này.');modal(`<h2>${t('Review your stay inquiry','Xem lại yêu cầu lưu trú')}</h2><p>${esc(data.name)} · ${esc(data.contact)}<br>${esc(data.checkin)} → ${esc(data.checkout)} · ${esc(data.guests)} ${t('guests','khách')}<br>${esc(c.apartments.find(a=>a.id===data.apartment)?.name||t('Help me choose','Tư vấn giúp tôi'))}</p><p>${esc(status.textContent)}</p>${link(t('Call ChiHome','Gọi ChiHome'),c.contact.phoneUrl)}`);return;}
const b=f.querySelector('[type=submit]');b.disabled=true;status.textContent=t('Sending your inquiry…','Đang gửi yêu cầu…');try{const response=await fetch(c.backend.endpoint,{method:'POST',headers:{'Content-Type':'application/json',...(c.backend.nonce?{'X-WP-Nonce':c.backend.nonce}:{})},body:JSON.stringify(data)});const result=await response.json();if(!response.ok||result.accepted!==true)throw Error('not accepted');status.textContent='';track('lead_submission',{apartment:data.apartment,lead_id:result.id||''});showThankYou(data,result.id);f.reset();f._validateDates();}catch{status.textContent=t('Your inquiry could not be sent. Please try again or call ChiHome.','Chưa gửi được yêu cầu. Vui lòng thử lại hoặc gọi ChiHome.')}finally{b.disabled=false;}}

function bindElementor(){
 document.documentElement.lang=lang;
 Object.entries(c.tokens).forEach(([k,v])=>{if(/^#[0-9a-f]{6}$/i.test(v))document.documentElement.style.setProperty('--'+k,v)});
 const d=root.querySelector('#detail-dialog');
 if(d){d.querySelector('.dialog-close').onclick=()=>d.close();d.addEventListener('close',()=>d.querySelector('.dialog-body').innerHTML='');d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});}
 root.querySelectorAll('#inquiry').forEach(f=>{dates(f);f.elements.contact.addEventListener('input',()=>f.elements.contact.setCustomValidity(''));f.onsubmit=submit;});
 root.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;const href=a.getAttribute('href')||'';
 if(href.startsWith('#chi-detail-')){e.preventDefault();const p=c.apartments.find(p=>p.id===href.slice(12));if(p)openApartment(p);}
 if(href.startsWith('#chi-book-')){e.preventDefault();const f=root.querySelector('#inquiry');if(f){f.elements.apartment.value=href.slice(10);root.querySelector('#contact').scrollIntoView();f.elements.name.focus({preventScroll:true});}}
 });
}

async function init(){try{c=window.CHIHOME_CONFIG||await(await fetch('content.json')).json();lang=window.CHIHOME_ELEMENTOR_LANGUAGE||localStorage.getItem('chihome-language')||c.defaultLanguage||'en';if(!['en','vi'].includes(lang))lang='en';utm();if(window.CHIHOME_ELEMENTOR){bindElementor()}else{render()}if(c.analytics.enabled&&/^GTM-[A-Z0-9]+$/.test(c.analytics.gtmId)){window.dataLayer=window.dataLayer||[];window.dataLayer.push({'gtm.start':Date.now(),event:'gtm.js'});const s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtm.js?id='+c.analytics.gtmId;document.head.append(s)}}catch(e){root.innerHTML='<p style="padding:40px">ChiHome preview could not load. <a href="https://chihome.vn">Visit ChiHome.vn ↗</a></p>';console.error(e)}}init();
})();
